        // inlining of macro Gia_ManForEachCi
        for  i = 0; (i < Vec_IntSize(pAdd.vCis)) && ((pObj) = Gia_ManCi(pAdd, i)); i++  {
            pObj.Value = Gia_Obj2Lit( pBase, Gia_ManCi(pBase, i) );
        }
    }
    // inlining of macro Gia_ManForEachAnd
