        best_i = i;
        for  j = i+1; j < nSize; j++  {
            if Abc_Lit2LitL(pCostLits, pArray[j]) > Abc_Lit2LitL(pCostLits, pArray[best_i]) {
                best_i = j; }
        }
        // inlining of macro ABC_SWAP
        { var t int32  = pArray[i]; pArray[i] = pArray[best_i]; pArray[best_i] = t; };
    }
}

