}
func Acec_ComputeEquivClasses(pOne *Gia_Man_t, pTwo *Gia_Man_t, pvMap1 **Vec_Int_t, pvMap2 **Vec_Int_t) {
    var clk abctime  = Abc_Clock();
    var pBase, pRepr *Gia_Man_t;
